WITH valid_accounts AS (SELECT *, SUBSTRING(account_type, 1, 4) AS account_type_prefix FROM accounts WHERE balance < 78000 OR opened_date >= '2024-02-01'), account_type_summary AS (SELECT account_type, DATE_TRUNC('MONTH', opened_date) AS opened_month, AVG(balance) AS avg_balance FROM valid_accounts GROUP BY account_type, DATE_TRUNC('MONTH', opened_date)) SELECT account_type, opened_month FROM account_type_summary ORDER BY account_type DESC;
